import{s as e}from"./i18n-BSBp_gjh.js";import{t}from"./buildPage-DWQZYYcs.js";var n=t({slug:`video-to-shorts`,heroTitle:e({defaultMessage:`Turn long videos into shorts in minutes`,id:`666ffd11f0`}),heroSubtitle:e({defaultMessage:`Perplexity Computer analyzes your video, identifies the most engaging moments, and delivers timestamped clips with captions and hooks — automatically.`,id:`880c9d1296`}),inputUrlCta:e({defaultMessage:`Clip this video`,id:`16ec88c1e0`}),inputUrlPlaceholder:`e.g. https://youtube.com/watch?v=...`,inputUrlPrefill:e({defaultMessage:`Go to {url} and analyze the full video to identify the most engaging moments for short-form content. (1) Watch the entire video and map its structure — intro, key segments, highlights, emotional peaks, and conclusion. (2) Identify the top 5-10 clip-worthy segments based on engagement signals — surprising statements, emotional reactions, humor, controversy, actionable advice, and visual interest. (3) For each clip, define precise start and end timestamps optimized for 30-60 second short-form format. (4) Write an attention-grabbing hook for each clip — the opening text or voiceover designed to stop scrolling in the first 2 seconds. (5) Write platform-optimized captions for each clip — TikTok, YouTube Shorts, and Instagram Reels — with relevant hashtags and calls-to-action. (6) Suggest the best posting order and scheduling strategy based on content type and platform algorithm patterns. (7) Deliver a complete clip sheet with timestamps, hooks, captions, hashtags, and scheduling recommendations for every clip.`,id:`45d4aa36d9`}),heroOverlaySteps:[e({defaultMessage:`Analyzing full video structure and identifying engagement peaks`,id:`7b4e2a388f`}),e({defaultMessage:`Selecting top clip-worthy segments with precise timestamps`,id:`e74e562e6f`}),e({defaultMessage:`Writing scroll-stopping hooks and platform-optimized captions`,id:`51666c3d99`}),e({defaultMessage:`Complete clip sheet with timestamps, hooks, and scheduling — ready to post`,id:`e942f50b3c`})],generatingSteps:[e({defaultMessage:`Visiting {url} to analyze the full video and map its structure`,id:`3d1c893ca5`}),e({defaultMessage:`Designing an agent to identify engagement peaks and clip-worthy moments`,id:`47c709a513`}),e({defaultMessage:`Configuring hook writing and platform-specific caption generation`,id:`4bc5ebb386`}),e({defaultMessage:`Setting up deliverable with timestamps, captions, hashtags, and scheduling strategy`,id:`dca9270874`})],featureSectionTitle:e({defaultMessage:`From long video to viral clips`,id:`6de18d75a0`}),featureCardTitles:[e({defaultMessage:`Connects to your creator stack`,id:`23eb2fb131`}),e({defaultMessage:`Outputs you can post`,id:`f2cf765ea8`})],featureCardDescriptions:[e({defaultMessage:`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,id:`799bfa0fff`}),e({defaultMessage:`YouTube, TikTok, Instagram, Google Sheets — Computer plugs into your tools so clip sheets, captions, and scheduling flow into one workflow.`,id:`27e61320cb`}),e({defaultMessage:`Timestamped clips. Scroll-stopping hooks. Platform captions. Scheduling suggestions. Computer delivers everything you need to repurpose one video into a week of shorts.`,id:`6c70fe970c`})],capabilitySectionTitle:e({defaultMessage:`Your video editor, on autopilot`,id:`18b6bc185b`}),capabilitySectionSubtitle:e({defaultMessage:`Paste a video URL, step away, come back to ready-to-post clips.`,id:`fe05b9a680`}),capabilityCards:[{title:e({defaultMessage:`Engagement Analysis`,id:`e1b50283e8`}),description:e({defaultMessage:`Computer can analyze your full video — mapping structure, identifying emotional peaks, surprising moments, and segments with the highest viral potential.`,id:`f1f76ef612`})},{title:e({defaultMessage:`Clip Identification`,id:`203243cf01`}),description:e({defaultMessage:`Computer can select the top clip-worthy segments — defining precise start and end timestamps optimized for 30-60 second short-form format.`,id:`02da0e3746`})},{title:e({defaultMessage:`Hook Writing`,id:`31580d7365`}),description:e({defaultMessage:`Computer can write attention-grabbing hooks for each clip — opening lines designed to stop scrolling in the first 2 seconds on TikTok, Shorts, and Reels.`,id:`e80a94ac0e`})},{title:e({defaultMessage:`Connect Your Tools`,id:`bf5d8ba7a6`}),description:e({defaultMessage:`Computer can read from YouTube, TikTok, Instagram, Google Sheets, and more — build workflows across your entire creator stack.`,id:`47388395c3`})},{title:e({defaultMessage:`Remember & Learn`,id:`8bf59582ce`}),description:e({defaultMessage:`Computer can remember your top-performing clips, audience preferences, and content themes across sessions — so every video gets smarter recommendations.`,id:`3867fa9925`})},{title:e({defaultMessage:`Performance Tracking`,id:`795aae6691`}),description:e({defaultMessage:`Computer can monitor clip performance across platforms — and identify which hooks, formats, and topics drive the most views and engagement.`,id:`83418698d4`})}]});export{n as default};
